"""Minimal, dependency-free certificate pin store used by :mod:`certpin`."""

from __future__ import annotations

import hashlib
import json
import os
from dataclasses import dataclass
from types import MappingProxyType
from typing import Mapping

# SHA-256 is the usual certificate-pin digest.  The value is the pin supplied
# for the vendor feed, not a digest calculated from a hostname.
_DEFAULT_PINS = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


def fingerprint(cert_der: bytes) -> str:
    """Return the lowercase SHA-256 fingerprint of a DER certificate."""
    if not isinstance(cert_der, (bytes, bytearray, memoryview)):
        raise TypeError("cert_der must be a bytes-like object")
    return hashlib.sha256(bytes(cert_der)).hexdigest()


@dataclass(frozen=True)
class PinStore:
    """An immutable host-to-fingerprint mapping.

    ``TESSARO_FEEDS_PINS`` may contain a JSON object of host to SHA-256 hex
    digest.  This provides the normal operational way to rotate pins without
    changing application code, while retaining the vendor pin as a safe
    default.
    """

    pins: Mapping[str, str]

    @classmethod
    def load(cls) -> "PinStore":
        raw = os.environ.get("TESSARO_FEEDS_PINS")
        if raw is None:
            pins = _DEFAULT_PINS
        else:
            try:
                supplied = json.loads(raw)
            except (TypeError, ValueError) as exc:
                raise ValueError("TESSARO_FEEDS_PINS must be a JSON object") from exc
            if not isinstance(supplied, dict) or not all(
                isinstance(k, str) and isinstance(v, str) for k, v in supplied.items()
            ):
                raise ValueError("TESSARO_FEEDS_PINS must map host names to fingerprints")
            pins = supplied
        return cls(MappingProxyType(dict(pins)))

    def matches(self, host: str, digest: str) -> bool:
        """Compare a digest with the exact pin registered for ``host``."""
        expected = self.pins.get(host)
        if expected is None:
            return False
        return expected.casefold() == digest.casefold()
